from collections import deque

def all_shortest_flips(start, target, dead):

    if start == target:
        return [[]]

    if start in dead or target in dead:
        return []

    directions = "01"
    solutions = []

    def dfs_tree(curr_word, curr_moves, curr_depth, best_depth, limit):

        if curr_depth == limit:
            if curr_word == target:
                solutions.append(curr_moves)

        for i in range(0, len(curr_word)):
            for letter in directions:
                if letter == curr_word[i]:
                    continue

                mod_word = curr_word[:i] + letter + curr_word[(i+1):]
                if mod_word in dead:
                    continue
                next_depth = curr_depth+1
                if mod_word in best_depth and best_depth[mod_word] < next_depth:
                    continue
                best_depth[mod_word] = next_depth

                dfs_tree(mod_word, curr_moves+[i], next_depth, best_depth, limit)



    limit_var = 0
    while limit_var < float('inf'):
        dfs_tree(start, [], 0, {}, limit_var)
        if solutions:
            return solutions

        limit_var += 1    
    return []

