from collections import deque

def coin_steps(n):

    queue = deque()
    visited_set = set()

    coins = [4, 3, 1]

    queue.append((n, 0))

    while queue:
        curr_sum, curr_coins = queue.popleft()
        if curr_sum in visited_set:
            continue

        visited_set.add(curr_sum)
        if curr_sum == 0:
            return curr_coins

        for coin in coins:
            if curr_sum - coin >= 0:
                queue.append((curr_sum - coin, curr_coins+1))
                pass
            else:
                continue



    return 0

