from collections import deque

def jug_pours(cap_a, cap_b, target):

    if target == 0:
        return 0
    if target > max(cap_a, cap_b):
        return None

    solutions = []

    def bfs_tree(jug1_limit, jug2_limit, limit):

        queue = deque()
        visited = {(0, 0)}

        queue.append((0, 0, 0, 0))

        while queue:
            curr_1, curr_2, curr_depth, curr_moves = queue.popleft()

            if curr_depth == limit:
                if curr_1 == target or curr_2 == target:
                    solutions.append(curr_moves)
                continue

            next_states = []

            # move 1 - fill either jug completely
            if curr_1 != jug1_limit:
                next_states.append((jug1_limit, curr_2))
            if curr_2 != jug2_limit:
                next_states.append((curr_1, jug2_limit))

            # move 2 - empty either jug completely
            if curr_1 > 0:
                next_states.append((0, curr_2))
            if curr_2 > 0:
                next_states.append((curr_1, 0))

            # move 3 - pour until the source empties or the destination fills
            pour = min(curr_1, jug2_limit - curr_2)
            if pour > 0:
                next_states.append((curr_1 - pour, curr_2 + pour))

            pour = min(curr_2, jug1_limit - curr_1)
            if pour > 0:
                next_states.append((curr_1 + pour, curr_2 - pour))

            for state in next_states:
                if state in visited:
                    continue
                visited.add(state)
                queue.append((state[0], state[1], curr_depth + 1, curr_moves + 1))

    limit_var = 0
    max_limit = cap_a * cap_b + 1
    while limit_var <= max_limit:
        bfs_tree(cap_a, cap_b, limit_var)
        if solutions:
            return solutions[0]
        limit_var += 1
    return None

