from collections import deque

def ladder_length(start, target, words):

    if start == target:
        return 0
    directions = "abcdefghijklmnopqrstuvwxyz"
    solutions = []

    def bfs_tree(word, moves, limit):
        queue = deque()
        visited_set = set()
        queue.append((word, moves, 0))

        while queue:
            curr_word, curr_moves, curr_depth = queue.popleft()

            if curr_word in visited_set:
                continue

            visited_set.add(curr_word)

            if curr_depth == limit:
                if curr_word == target:
                    solutions.append(curr_moves)
                continue

            for i in range(0, len(curr_word)):
                for letter in directions:
                    if letter == curr_word[i]:
                        continue

                    mod_word = curr_word[:i] + letter + curr_word[(i+1):]
                    if mod_word not in words:
                        continue

                    queue.append((mod_word, curr_moves+1, curr_depth+1))

    limit_var = 0
    max_limit = len(words) + 1
    while limit_var <= max_limit:
        bfs_tree(start, 0, limit_var)
        if solutions:
            return solutions[0]
        limit_var += 1

    return None
